function morseCode = morseEncoding(phrase)
% This function converts a given phrase to its Morse Code representation
% according to the International Morse Code standard.

% Define the Morse Code mapping
morseMapping = {'. ', '-...', '-.-.', '-.. ', '. ', '..- ', '--.', '.... ', '. ', '.. ', '.-- ', '--', '.-..', '-- ', '-.', '-. '};

% Convert the input phrase to uppercase and split it into individual characters
phraseUpper = upper(phrase);
characters = strsplit(phraseUpper);

% Initialize variables for storing the Morse Code output
morseCodeOutput = [];

% Loop through each character in the input phrase and generate its Morse Code representation
for I = 1:length(characters)
    % Check if the current character is a space or a punctuation mark
    if ~isalpha(characters(i)(end)) && ~isnumeric(characters(i)(end))
        % If yes, add a pause between words
        morseCodeOutput(end+1:end) = ['/', ' '];
        continue;
    end

    % Find the index of the current character in the Morse Code mapping array
    morseIndex = strfind(lower(characters(i)), {'a', 'b', 'c', 'd', 'e', 'f', 'g', 'h', 'i', 'j', 'k', 'l', 'm', 'n', 'o', 'p', 'q', 'r', 's', 't', 'u', 'v', 'w', 'x', 'y', 'z'}, 'first');

    % Add the corresponding Morse Code sequence to the output array
    morseCodeOutput(end+1:end) = morseMapping(morseIndex);
end

% Remove any trailing spaces and pauses from the output array
morseCode = morseCodeOutput(1:find(~ismember(' ', morseCodeOutput), inf, 'last')-1);
end
