// Bubble sort function, takes the array and its size as arguments
void bubbleSort(int arr[], int n) {
    bool swapped = true; // flag to keep track of whether any swaps were made in the last iteration
    int end = n - 1; // index of the rightmost element

    while (swapped) { // iterate until no more swaps are needed
        swapped = false; // reset flag

        for (int i = 0; i < end; ++i) { // compare adjacent elements from left to right
            if (arr[i] > arr[i+1]) { // swap them if they're out of order
                int temp = arr[i];
                arr[i] = arr[i+1];
                arr[i+1] = temp;
                swapped = true; // set flag if a swap was made
            }
        }

        --end; // move the boundary of the unsorted region one position to the left
    }
}

