function getMostRelevantProtocol(inputData) {
  const { sourceIP, destinationIP, port, payload } = inputData;

  // Check for IPv6
  if (/^(?:[0-9A-Fa-f]{1,4}:){7}[0-9A-Fa-f]{1,4}$/.test(sourceIP) && /^(?:[0-9A-Fa-f]{1,4}:){7}[0-9A-Fa-f]{1,4}$/.test(destinationIP)) {
    return 'IPv6';
  }

  // Convert payload to array of lines
  const lines = payload.split('\n');

  // Check for HTTP GET request
  const httpRequest = lines.some((line) => line.trim().startsWith('GET'));

  // Return HTTP if found, else fallback to UDP
  return httpRequest ? 'HTTP' : 'UDP';
}
```

